namespace
{
	constexpr int MaxResources = 256;
	constexpr int FirstDynamicResource = 128;   // [1..128) FSR 3 resources, [128..256) game resources registered for one frame
	constexpr int MaxMips = 16;
	constexpr int ConstantBufferSlots = 4;
	constexpr UINT ConstantBufferSize = 1024;
	constexpr size_t StagingSize = 16 * 1024;

	struct BackendResource
	{
		ID3D11Resource* resource = nullptr;
		ID3D11ShaderResourceView* srv = nullptr;
		ID3D11UnorderedAccessView* uav[MaxMips] = {};
		DXGI_FORMAT format = DXGI_FORMAT_UNKNOWN;
		FfxApiResourceDescription description = {};
		bool external = false;

		void Release()
		{
			Utilities::SafeRelease(srv);
			for (ID3D11UnorderedAccessView*& view : uav)
				Utilities::SafeRelease(view);
			Utilities::SafeRelease(resource);   // Registered game resources are AddRef'ed too
			format = DXGI_FORMAT_UNKNOWN;
			description = {};
			external = false;
		}
	};

	/*
		FSR 2 and FSR 3 both declare a global FfxGpuJobDescription with different layouts. std::vector<FfxGpuJobDescription>
		would be the same template instance in both object files and the linker keeps only one, so each backend wraps it.
	*/
	struct QueuedJob
	{
		FfxGpuJobDescription job;
	};

	struct Backend
	{
		ID3D11Device* device = nullptr;
		BackendResource resources[MaxResources];
		int nextStatic = 1;   // 0 = FFX_FSR3UPSCALER_RESOURCE_IDENTIFIER_NULL
		int nextDynamic = FirstDynamicResource;
		std::vector<QueuedJob> jobs;
		alignas(16) uint8_t staging[StagingSize];
		size_t stagingOffset = 0;
		ID3D11Buffer* constantBuffers[ConstantBufferSlots] = {};
		ID3D11SamplerState* pointClamp = nullptr;
		ID3D11SamplerState* linearClamp = nullptr;
		Utilities::ComputeState savedState;
	};

	Backend* backend = nullptr;

	DXGI_FORMAT ToDxgi(uint32_t format)
	{
		switch (format)
		{
		case FFX_API_SURFACE_FORMAT_R32G32B32A32_TYPELESS: return DXGI_FORMAT_R32G32B32A32_FLOAT;
		case FFX_API_SURFACE_FORMAT_R32G32B32A32_UINT: return DXGI_FORMAT_R32G32B32A32_UINT;
		case FFX_API_SURFACE_FORMAT_R32G32B32A32_FLOAT: return DXGI_FORMAT_R32G32B32A32_FLOAT;
		case FFX_API_SURFACE_FORMAT_R16G16B16A16_FLOAT: return DXGI_FORMAT_R16G16B16A16_FLOAT;
		case FFX_API_SURFACE_FORMAT_R32G32_FLOAT: return DXGI_FORMAT_R32G32_FLOAT;
		case FFX_API_SURFACE_FORMAT_R8_UINT: return DXGI_FORMAT_R8_UINT;
		case FFX_API_SURFACE_FORMAT_R32_UINT: return DXGI_FORMAT_R32_UINT;
		case FFX_API_SURFACE_FORMAT_R8G8B8A8_TYPELESS: return DXGI_FORMAT_R8G8B8A8_UNORM;
		case FFX_API_SURFACE_FORMAT_R8G8B8A8_UNORM: return DXGI_FORMAT_R8G8B8A8_UNORM;
		case FFX_API_SURFACE_FORMAT_R11G11B10_FLOAT: return DXGI_FORMAT_R11G11B10_FLOAT;
		case FFX_API_SURFACE_FORMAT_R16G16_FLOAT: return DXGI_FORMAT_R16G16_FLOAT;
		case FFX_API_SURFACE_FORMAT_R16G16_UINT: return DXGI_FORMAT_R16G16_UINT;
		case FFX_API_SURFACE_FORMAT_R16_FLOAT: return DXGI_FORMAT_R16_FLOAT;
		case FFX_API_SURFACE_FORMAT_R16_UINT: return DXGI_FORMAT_R16_UINT;
		case FFX_API_SURFACE_FORMAT_R16_UNORM: return DXGI_FORMAT_R16_UNORM;
		case FFX_API_SURFACE_FORMAT_R16_SNORM: return DXGI_FORMAT_R16_SNORM;
		case FFX_API_SURFACE_FORMAT_R8_UNORM: return DXGI_FORMAT_R8_UNORM;
		case FFX_API_SURFACE_FORMAT_R8G8_UNORM: return DXGI_FORMAT_R8G8_UNORM;
		case FFX_API_SURFACE_FORMAT_R32_FLOAT: return DXGI_FORMAT_R32_FLOAT;
		default: return DXGI_FORMAT_UNKNOWN;
		}
	}

	UINT BytesPerPixel(DXGI_FORMAT format)
	{
		switch (format)
		{
		case DXGI_FORMAT_R32G32B32A32_FLOAT:
		case DXGI_FORMAT_R32G32B32A32_UINT: return 16;
		case DXGI_FORMAT_R16G16B16A16_FLOAT:
		case DXGI_FORMAT_R32G32_FLOAT: return 8;
		case DXGI_FORMAT_R32_UINT:
		case DXGI_FORMAT_R8G8B8A8_UNORM:
		case DXGI_FORMAT_R11G11B10_FLOAT:
		case DXGI_FORMAT_R16G16_FLOAT:
		case DXGI_FORMAT_R16G16_UINT:
		case DXGI_FORMAT_R32_FLOAT: return 4;
		case DXGI_FORMAT_R16_FLOAT:
		case DXGI_FORMAT_R16_UINT:
		case DXGI_FORMAT_R16_UNORM:
		case DXGI_FORMAT_R16_SNORM:
		case DXGI_FORMAT_R8G8_UNORM: return 2;
		default: return 1;
		}
	}

	bool IsIntegerFormat(DXGI_FORMAT format)
	{
		return format == DXGI_FORMAT_R32_UINT || format == DXGI_FORMAT_R32G32B32A32_UINT || format == DXGI_FORMAT_R16G16_UINT ||
		       format == DXGI_FORMAT_R16_UINT || format == DXGI_FORMAT_R8_UINT;
	}

	/* View format for game textures, which are often TYPELESS */
	DXGI_FORMAT TypedFormat(DXGI_FORMAT format)
	{
		switch (format)
		{
		case DXGI_FORMAT_R16G16B16A16_TYPELESS: return DXGI_FORMAT_R16G16B16A16_FLOAT;
		case DXGI_FORMAT_R32G32B32A32_TYPELESS: return DXGI_FORMAT_R32G32B32A32_FLOAT;
		case DXGI_FORMAT_R32G32_TYPELESS: return DXGI_FORMAT_R32G32_FLOAT;
		case DXGI_FORMAT_R16G16_TYPELESS: return DXGI_FORMAT_R16G16_FLOAT;
		case DXGI_FORMAT_R32_TYPELESS: return DXGI_FORMAT_R32_FLOAT;
		case DXGI_FORMAT_R10G10B10A2_TYPELESS: return DXGI_FORMAT_R10G10B10A2_UNORM;
		case DXGI_FORMAT_R8G8B8A8_TYPELESS: return DXGI_FORMAT_R8G8B8A8_UNORM;
		case DXGI_FORMAT_B8G8R8A8_TYPELESS: return DXGI_FORMAT_B8G8R8A8_UNORM;
		case DXGI_FORMAT_R16_TYPELESS: return DXGI_FORMAT_R16_FLOAT;
		case DXGI_FORMAT_R8_TYPELESS: return DXGI_FORMAT_R8_UNORM;
		case DXGI_FORMAT_R24G8_TYPELESS: return DXGI_FORMAT_R24_UNORM_X8_TYPELESS;
		case DXGI_FORMAT_R32G8X24_TYPELESS: return DXGI_FORMAT_R32_FLOAT_X8X24_TYPELESS;
		default: return format;
		}
	}

	BackendResource* Get(FfxResourceInternal handle)
	{
		if (backend == nullptr || handle.internalIndex <= 0 || handle.internalIndex >= MaxResources)
			return nullptr;
		BackendResource* r = &backend->resources[handle.internalIndex];
		return r->resource ? r : nullptr;
	}

	void LogMessage(uint32_t type, const wchar_t* message)
	{
		static int count = 0;
		if (message && count++ < 50)
			Utilities::Log::Write("FSR 3 %s: %ls", type == FFX_API_MESSAGE_TYPE_ERROR ? "error" : "warning", message);
	}

	FfxErrorCode GetEffectGpuMemoryUsage(FfxInterface*, FfxUInt32, FfxApiEffectMemoryUsage* usage)
	{
		if (usage)
			*usage = {};
		return FFX_OK;
	}

	FfxErrorCode CreateBackendContext(FfxInterface* iface, FfxEffect, FfxEffectBindlessConfig*, FfxUInt32* effectContextId)
	{
		if (backend == nullptr)
			backend = new Backend();
		backend->device = static_cast<ID3D11Device*>(iface->device);
		*effectContextId = 0;

		D3D11_BUFFER_DESC bufferDesc = {};
		bufferDesc.ByteWidth = ConstantBufferSize;
		bufferDesc.Usage = D3D11_USAGE_DYNAMIC;
		bufferDesc.BindFlags = D3D11_BIND_CONSTANT_BUFFER;
		bufferDesc.CPUAccessFlags = D3D11_CPU_ACCESS_WRITE;
		for (ID3D11Buffer*& buffer : backend->constantBuffers)
			if (buffer == nullptr && FAILED(backend->device->CreateBuffer(&bufferDesc, nullptr, &buffer)))
				return FFX_ERROR_BACKEND_API_ERROR;

		D3D11_SAMPLER_DESC samplerDesc = {};
		samplerDesc.AddressU = samplerDesc.AddressV = samplerDesc.AddressW = D3D11_TEXTURE_ADDRESS_CLAMP;
		samplerDesc.ComparisonFunc = D3D11_COMPARISON_NEVER;
		samplerDesc.MaxLOD = D3D11_FLOAT32_MAX;
		samplerDesc.Filter = D3D11_FILTER_MIN_MAG_MIP_POINT;
		if (backend->pointClamp == nullptr && FAILED(backend->device->CreateSamplerState(&samplerDesc, &backend->pointClamp)))
			return FFX_ERROR_BACKEND_API_ERROR;
		samplerDesc.Filter = D3D11_FILTER_MIN_MAG_MIP_LINEAR;
		if (backend->linearClamp == nullptr && FAILED(backend->device->CreateSamplerState(&samplerDesc, &backend->linearClamp)))
			return FFX_ERROR_BACKEND_API_ERROR;
		return FFX_OK;
	}

	/* Waves 32..64 select the Lanczos LUT permutation, below 6.6 there is no forced wave64 */
	FfxErrorCode GetDeviceCapabilities(FfxInterface*, FfxDeviceCapabilities* capabilities)
	{
		*capabilities = {};
		capabilities->maximumSupportedShaderModel = FFX_SHADER_MODEL_5_1;
		capabilities->waveLaneCountMin = 32;
		capabilities->waveLaneCountMax = 64;
		return FFX_OK;
	}

	FfxErrorCode DestroyBackendContext(FfxInterface*, FfxUInt32)
	{
		if (backend == nullptr)
			return FFX_OK;
		for (BackendResource& r : backend->resources)
			r.Release();
		for (ID3D11Buffer*& buffer : backend->constantBuffers)
			Utilities::SafeRelease(buffer);
		Utilities::SafeRelease(backend->pointClamp);
		Utilities::SafeRelease(backend->linearClamp);
		delete backend;
		backend = nullptr;
		return FFX_OK;
	}

	FfxErrorCode CreateResource(FfxInterface*, const FfxCreateResourceDescription* create, FfxUInt32, FfxResourceInternal* out)
	{
		if (backend == nullptr || backend->nextStatic + 1 >= FirstDynamicResource)
			return FFX_ERROR_OUT_OF_MEMORY;

		const FfxApiResourceDescription& d = create->resourceDescription;
		const DXGI_FORMAT format = ToDxgi(d.format);
		if (format == DXGI_FORMAT_UNKNOWN || d.type != FFX_API_RESOURCE_TYPE_TEXTURE2D)
		{
			Utilities::Log::Write("FSR 3: %ls has unsupported type %u / format %u", create->name ? create->name : L"?", d.type, d.format);
			return FFX_ERROR_INVALID_ENUM;
		}

		UINT width = d.width ? d.width : 1;
		UINT height = d.height ? d.height : 1;
		UINT mips = d.mipCount;
		if (mips == 0)
		{
			UINT largest = width > height ? width : height;
			while (largest > 0) { ++mips; largest >>= 1; }
		}
		if (mips > MaxMips)
			mips = MaxMips;

		const bool uav = (d.usage & FFX_API_RESOURCE_USAGE_UAV) != 0;

		D3D11_TEXTURE2D_DESC desc = {};
		desc.Width = width;
		desc.Height = height;
		desc.MipLevels = mips;
		desc.ArraySize = 1;
		desc.Format = format;
		desc.SampleDesc.Count = 1;
		desc.Usage = D3D11_USAGE_DEFAULT;
		desc.BindFlags = D3D11_BIND_SHADER_RESOURCE | (uav ? D3D11_BIND_UNORDERED_ACCESS : 0);

		/* Init data is either a copy of a buffer or one repeated byte */
		const UINT pitch = width * BytesPerPixel(format);
		std::vector<uint8_t> filled;
		const void* initial = nullptr;
		if (create->initData.type == FFX_RESOURCE_INIT_DATA_TYPE_BUFFER && create->initData.buffer)
			initial = create->initData.buffer;
		else if (create->initData.type == FFX_RESOURCE_INIT_DATA_TYPE_VALUE)
		{
			filled.assign(static_cast<size_t>(pitch) * height, create->initData.value);
			initial = filled.data();
		}

		D3D11_SUBRESOURCE_DATA data = {};
		data.pSysMem = initial;
		data.SysMemPitch = pitch;
		data.SysMemSlicePitch = pitch * height;

		ID3D11Texture2D* texture = nullptr;
		HRESULT result = backend->device->CreateTexture2D(&desc, (initial && mips == 1) ? &data : nullptr, &texture);
		if (FAILED(result))
		{
			Utilities::Log::Write("FSR 3: CreateTexture2D %ls %ux%u format %u failed 0x%08X", create->name ? create->name : L"?", width, height,
			                      static_cast<unsigned>(format), static_cast<unsigned>(result));
			return FFX_ERROR_BACKEND_API_ERROR;
		}

		int index = backend->nextStatic++;
		BackendResource& r = backend->resources[index];
		r.resource = texture;
		r.format = format;
		r.description = d;
		r.description.width = width;
		r.description.height = height;
		r.description.mipCount = mips;

		/* ffxSafeReleaseCopyResource frees index + 1, where the DX12 backend keeps the upload copy */
		if (create->initData.type == FFX_RESOURCE_INIT_DATA_TYPE_BUFFER || create->initData.type == FFX_RESOURCE_INIT_DATA_TYPE_VALUE)
			backend->nextStatic++;

		if (FAILED(backend->device->CreateShaderResourceView(texture, nullptr, &r.srv)))
			return FFX_ERROR_BACKEND_API_ERROR;
		if (uav)
		{
			for (UINT mip = 0; mip < mips; ++mip)
			{
				D3D11_UNORDERED_ACCESS_VIEW_DESC uavDesc = {};
				uavDesc.Format = format;
				uavDesc.ViewDimension = D3D11_UAV_DIMENSION_TEXTURE2D;
				uavDesc.Texture2D.MipSlice = mip;
				if (FAILED(backend->device->CreateUnorderedAccessView(texture, &uavDesc, &r.uav[mip])))
					return FFX_ERROR_BACKEND_API_ERROR;
			}
		}

		out->internalIndex = index;
		return FFX_OK;
	}

	FfxErrorCode RegisterResource(FfxInterface*, const FfxApiResource* in, FfxUInt32, FfxResourceInternal* out)
	{
		out->internalIndex = 0;
		if (backend == nullptr || in == nullptr || in->resource == nullptr)
			return FFX_OK;
		if (backend->nextDynamic >= MaxResources)
			return FFX_ERROR_OUT_OF_MEMORY;

		ID3D11Resource* resource = static_cast<ID3D11Resource*>(in->resource);
		D3D11_RESOURCE_DIMENSION dimension = D3D11_RESOURCE_DIMENSION_UNKNOWN;
		resource->GetType(&dimension);
		if (dimension != D3D11_RESOURCE_DIMENSION_TEXTURE2D)
			return FFX_ERROR_INVALID_ARGUMENT;

		D3D11_TEXTURE2D_DESC desc;
		static_cast<ID3D11Texture2D*>(resource)->GetDesc(&desc);
		const DXGI_FORMAT viewFormat = TypedFormat(desc.Format);

		int index = backend->nextDynamic++;
		BackendResource& r = backend->resources[index];
		resource->AddRef();
		r.resource = resource;
		r.external = true;
		r.format = viewFormat;
		r.description.type = FFX_API_RESOURCE_TYPE_TEXTURE2D;
		r.description.width = desc.Width;
		r.description.height = desc.Height;
		r.description.depth = 1;
		r.description.mipCount = desc.MipLevels;

		if (desc.BindFlags & D3D11_BIND_SHADER_RESOURCE)
		{
			D3D11_SHADER_RESOURCE_VIEW_DESC srvDesc = {};
			srvDesc.Format = viewFormat;
			srvDesc.ViewDimension = D3D11_SRV_DIMENSION_TEXTURE2D;
			srvDesc.Texture2D.MipLevels = desc.MipLevels;
			backend->device->CreateShaderResourceView(resource, &srvDesc, &r.srv);
		}
		if (desc.BindFlags & D3D11_BIND_UNORDERED_ACCESS)
		{
			D3D11_UNORDERED_ACCESS_VIEW_DESC uavDesc = {};
			uavDesc.Format = viewFormat;
			uavDesc.ViewDimension = D3D11_UAV_DIMENSION_TEXTURE2D;
			backend->device->CreateUnorderedAccessView(resource, &uavDesc, &r.uav[0]);
		}

		out->internalIndex = index;
		return FFX_OK;
	}

	FfxApiResource GetResource(FfxInterface*, FfxResourceInternal handle)
	{
		FfxApiResource result = {};
		if (BackendResource* r = Get(handle))
		{
			result.resource = r->resource;
			result.description = r->description;
		}
		return result;
	}

	FfxErrorCode UnregisterResources(FfxInterface*, FfxCommandList, FfxUInt32)
	{
		if (backend == nullptr)
			return FFX_OK;
		for (int i = FirstDynamicResource; i < backend->nextDynamic; ++i)
			backend->resources[i].Release();
		backend->nextDynamic = FirstDynamicResource;
		return FFX_OK;
	}

	FfxErrorCode RegisterStaticResource(FfxInterface*, const FfxStaticResourceDescription*, FfxUInt32)
	{
		return FFX_ERROR_INVALID_ARGUMENT;
	}

	FfxApiResourceDescription GetResourceDescription(FfxInterface*, FfxResourceInternal handle)
	{
		BackendResource* r = Get(handle);
		return r ? r->description : FfxApiResourceDescription{};
	}

	FfxErrorCode DestroyResource(FfxInterface*, FfxResourceInternal handle, FfxUInt32)
	{
		BackendResource* r = Get(handle);
		if (r && r->external == false)
			r->Release();
		return FFX_OK;
	}

	FfxErrorCode MapResource(FfxInterface*, FfxResourceInternal, void**)
	{
		return FFX_ERROR_INVALID_ARGUMENT;
	}

	FfxErrorCode UnmapResource(FfxInterface*, FfxResourceInternal)
	{
		return FFX_ERROR_INVALID_ARGUMENT;
	}

	/* Constants live in CPU memory until ExecuteGpuJobs uploads them */
	FfxErrorCode StageConstantBufferData(FfxInterface*, void* data, FfxUInt32 size, FfxConstantBuffer* constantBuffer)
	{
		if (backend == nullptr || data == nullptr || constantBuffer == nullptr)
			return FFX_ERROR_INVALID_POINTER;

		const size_t aligned = (static_cast<size_t>(size) + 255) & ~static_cast<size_t>(255);
		if (aligned > ConstantBufferSize)
			return FFX_ERROR_INVALID_SIZE;
		if (backend->stagingOffset + aligned > StagingSize)
			backend->stagingOffset = 0;

		uint8_t* target = backend->staging + backend->stagingOffset;
		memcpy(target, data, size);
		backend->stagingOffset += aligned;

		constantBuffer->data = reinterpret_cast<uint32_t*>(target);
		constantBuffer->num32BitEntries = size / sizeof(uint32_t);
		return FFX_OK;
	}

	FfxErrorCode CreatePipeline(FfxInterface*, FfxShaderBlob* blob, const FfxPipelineDescription* description, FfxUInt32, FfxPipelineState* out)
	{
		memset(out, 0, sizeof(*out));
		if (description)
			wcsncpy_s(out->name, description->name, _TRUNCATE);

		/* Passes without a compiled shader (reactive mask generation, debug view) stay empty */
		if (blob == nullptr || blob->data == nullptr || blob->size == 0)
			return FFX_OK;

		ID3D11ComputeShader* shader = nullptr;
		HRESULT result = backend->device->CreateComputeShader(blob->data, blob->size, nullptr, &shader);
		if (FAILED(result))
		{
			Utilities::Log::Write("FSR 3: CreateComputeShader %ls failed 0x%08X", out->name, static_cast<unsigned>(result));
			return FFX_ERROR_BACKEND_API_ERROR;
		}

		/* ffx_fsr3upscaler.cpp matches resources to these bindings by name */
		ID3D11ShaderReflection* reflection = nullptr;
		if (FAILED(D3DReflect(blob->data, blob->size, IID_ID3D11ShaderReflection, reinterpret_cast<void**>(&reflection))))
		{
			shader->Release();
			return FFX_ERROR_BACKEND_API_ERROR;
		}

		D3D11_SHADER_DESC shaderDesc = {};
		reflection->GetDesc(&shaderDesc);
		for (UINT i = 0; i < shaderDesc.BoundResources; ++i)
		{
			D3D11_SHADER_INPUT_BIND_DESC bind = {};
			if (FAILED(reflection->GetResourceBindingDesc(i, &bind)))
				continue;

			FfxResourceBinding* target = nullptr;
			if (bind.Type == D3D_SIT_TEXTURE && out->srvTextureCount < FFX_MAX_NUM_SRVS)
				target = &out->srvTextureBindings[out->srvTextureCount++];
			else if (bind.Type == D3D_SIT_UAV_RWTYPED && out->uavTextureCount < FFX_MAX_NUM_UAVS)
				target = &out->uavTextureBindings[out->uavTextureCount++];
			else if (bind.Type == D3D_SIT_CBUFFER && out->constCount < FFX_MAX_NUM_CONST_BUFFERS)
				target = &out->constantBufferBindings[out->constCount++];
			if (target == nullptr)
				continue;

			target->slotIndex = bind.BindPoint;
			target->arrayIndex = 0;
			target->resourceIdentifier = 0;
			MultiByteToWideChar(CP_ACP, 0, bind.Name, -1, target->name, FFX_RESOURCE_NAME_SIZE);
		}
		reflection->Release();

		out->pipeline = shader;
		return FFX_OK;
	}

	FfxErrorCode DestroyPipeline(FfxInterface*, FfxPipelineState* pipeline, FfxUInt32)
	{
		if (pipeline && pipeline->pipeline)
		{
			static_cast<ID3D11ComputeShader*>(pipeline->pipeline)->Release();
			pipeline->pipeline = nullptr;
		}
		return FFX_OK;
	}

	FfxErrorCode ScheduleGpuJob(FfxInterface*, const FfxGpuJobDescription* job)
	{
		if (backend)
			backend->jobs.push_back(QueuedJob{ *job });
		return FFX_OK;
	}

	/* Clears every mip; integer formats need the uint variant, ClearUnorderedAccessViewFloat ignores them */
	void Clear(ID3D11DeviceContext* context, BackendResource* r, const float color[4])
	{
		for (ID3D11UnorderedAccessView* view : r->uav)
		{
			if (view == nullptr)
				continue;
			if (IsIntegerFormat(r->format))
			{
				const UINT values[4] = { static_cast<UINT>(color[0]), static_cast<UINT>(color[1]), static_cast<UINT>(color[2]), static_cast<UINT>(color[3]) };
				context->ClearUnorderedAccessViewUint(view, values);
			}
			else
				context->ClearUnorderedAccessViewFloat(view, color);
		}
	}

	void RunCompute(ID3D11DeviceContext* context, const FfxComputeJobDescription& job)
	{
		const FfxPipelineState* pipeline = job.pipeline;
		ID3D11ComputeShader* shader = pipeline ? static_cast<ID3D11ComputeShader*>(pipeline->pipeline) : nullptr;
		if (shader == nullptr)
			return;

		context->CSSetShader(shader, nullptr, 0);
		ID3D11SamplerState* samplers[2] = { backend->pointClamp, backend->linearClamp };
		context->CSSetSamplers(0, 2, samplers);

		for (uint32_t i = 0; i < pipeline->constCount; ++i)
		{
			const UINT slot = pipeline->constantBufferBindings[i].slotIndex;
			const FfxConstantBuffer& constants = job.cbs[i];
			if (slot >= ConstantBufferSlots || constants.data == nullptr)
				continue;
			D3D11_MAPPED_SUBRESOURCE mapped;
			if (SUCCEEDED(context->Map(backend->constantBuffers[slot], 0, D3D11_MAP_WRITE_DISCARD, 0, &mapped)))
			{
				memset(mapped.pData, 0, ConstantBufferSize);
				memcpy(mapped.pData, constants.data, constants.num32BitEntries * sizeof(uint32_t));
				context->Unmap(backend->constantBuffers[slot], 0);
			}
			context->CSSetConstantBuffers(slot, 1, &backend->constantBuffers[slot]);
		}

		for (uint32_t i = 0; i < pipeline->srvTextureCount; ++i)
		{
			BackendResource* r = Get(job.srvTextures[i].resource);
			ID3D11ShaderResourceView* srv = r ? r->srv : nullptr;
			context->CSSetShaderResources(pipeline->srvTextureBindings[i].slotIndex, 1, &srv);
		}
		for (uint32_t i = 0; i < pipeline->uavTextureCount; ++i)
		{
			BackendResource* r = Get(job.uavTextures[i].resource);
			const uint32_t mip = job.uavTextures[i].mip < MaxMips ? job.uavTextures[i].mip : 0;
			ID3D11UnorderedAccessView* uav = r ? r->uav[mip] : nullptr;
			context->CSSetUnorderedAccessViews(pipeline->uavTextureBindings[i].slotIndex, 1, &uav, nullptr);
		}

		context->Dispatch(job.dimensions[0], job.dimensions[1], job.dimensions[2]);

		Utilities::ComputeState::Unbind(context);
	}

	FfxErrorCode ExecuteGpuJobs(FfxInterface*, FfxCommandList commandList, FfxUInt32)
	{
		if (backend == nullptr)
			return FFX_ERROR_NULL_DEVICE;
		ID3D11DeviceContext* context = static_cast<ID3D11DeviceContext*>(commandList);

		backend->savedState.Save(context);
		Utilities::ComputeState::Unbind(context);

		for (const QueuedJob& queued : backend->jobs)
		{
			const FfxGpuJobDescription& job = queued.job;
			switch (job.jobType)
			{
			case FFX_GPU_JOB_CLEAR_FLOAT:
				if (BackendResource* r = Get(job.clearJobDescriptor.target))
					Clear(context, r, job.clearJobDescriptor.color);
				break;
			case FFX_GPU_JOB_COPY:
			{
				BackendResource* source = Get(job.copyJobDescriptor.src);
				BackendResource* destination = Get(job.copyJobDescriptor.dst);
				if (source && destination)
					context->CopyResource(destination->resource, source->resource);
				break;
			}
			case FFX_GPU_JOB_COMPUTE:
				RunCompute(context, job.computeJobDescriptor);
				break;
			default:
				/* Barriers and discards: D3D11 tracks hazards itself */
				break;
			}
		}
		backend->jobs.clear();
		backend->stagingOffset = 0;

		backend->savedState.Restore(context);
		return FFX_OK;
	}
}




/* Replaces ffx_fsr3upscaler_shaderblobs.cpp: one FXC-compiled permutation per pass, matching the context flags in FSR3.cpp */
extern "C" FfxErrorCode fsr3UpscalerGetPermutationBlobByIndex(FfxFsr3UpscalerPass passId, uint32_t, FfxShaderBlob* outBlob)
{
	memset(outBlob, 0, sizeof(*outBlob));
	switch (passId)
	{
	case FFX_FSR3UPSCALER_PASS_PREPARE_INPUTS: outBlob->data = g_Fsr3PrepareInputs; outBlob->size = sizeof(g_Fsr3PrepareInputs); break;
	case FFX_FSR3UPSCALER_PASS_LUMA_PYRAMID: outBlob->data = g_Fsr3LumaPyramid; outBlob->size = sizeof(g_Fsr3LumaPyramid); break;
	case FFX_FSR3UPSCALER_PASS_SHADING_CHANGE_PYRAMID: outBlob->data = g_Fsr3ShadingChangePyramid; outBlob->size = sizeof(g_Fsr3ShadingChangePyramid); break;
	case FFX_FSR3UPSCALER_PASS_SHADING_CHANGE: outBlob->data = g_Fsr3ShadingChange; outBlob->size = sizeof(g_Fsr3ShadingChange); break;
	case FFX_FSR3UPSCALER_PASS_PREPARE_REACTIVITY: outBlob->data = g_Fsr3PrepareReactivity; outBlob->size = sizeof(g_Fsr3PrepareReactivity); break;
	case FFX_FSR3UPSCALER_PASS_LUMA_INSTABILITY: outBlob->data = g_Fsr3LumaInstability; outBlob->size = sizeof(g_Fsr3LumaInstability); break;
	case FFX_FSR3UPSCALER_PASS_ACCUMULATE: outBlob->data = g_Fsr3Accumulate; outBlob->size = sizeof(g_Fsr3Accumulate); break;
	case FFX_FSR3UPSCALER_PASS_ACCUMULATE_SHARPEN: outBlob->data = g_Fsr3AccumulateSharpen; outBlob->size = sizeof(g_Fsr3AccumulateSharpen); break;
	case FFX_FSR3UPSCALER_PASS_RCAS: outBlob->data = g_Fsr3Rcas; outBlob->size = sizeof(g_Fsr3Rcas); break;
	default: break;
	}
	return FFX_OK;
}

extern "C" FfxErrorCode fsr3UpscalerIsWave64(uint32_t, bool& isWave64)
{
	isWave64 = false;
	return FFX_OK;
}

/* Declared in ffx_backends.h, only used by ffxFsr3UpscalerGetGpuMemoryUsage */
FfxErrorCode GetResourceSizeFromDescription(FfxDevice, const FfxCreateResourceDescription*, uint64_t* sizeInBytes, uint64_t* alignment)
{
	if (sizeInBytes)
		*sizeInBytes = 0;
	if (alignment)
		*alignment = 0;
	return FFX_OK;
}




bool FSR3::CheckDevice(ID3D11Device* device)
{
	if (device->GetFeatureLevel() < D3D_FEATURE_LEVEL_11_0)
	{
		errorReason = "FSR 3: NEEDS DIRECTX 11.0 GPU";
		return false;
	}

	/* FSR 3 passes read from R8, RG16F and RGBA32F UAVs */
	const DXGI_FORMAT formats[] = { DXGI_FORMAT_R8_UNORM, DXGI_FORMAT_R16G16_FLOAT, DXGI_FORMAT_R32G32B32A32_FLOAT };
	for (DXGI_FORMAT format : formats)
	{
		D3D11_FEATURE_DATA_FORMAT_SUPPORT2 support = {};
		support.InFormat = format;
		if (FAILED(device->CheckFeatureSupport(D3D11_FEATURE_FORMAT_SUPPORT2, &support, sizeof(support))) ||
		    (support.OutFormatSupport2 & D3D11_FORMAT_SUPPORT2_UAV_TYPED_LOAD) == 0)
		{
			Utilities::Log::Write("FSR 3: typed UAV loads are not supported for format %u - GPU or driver too old", static_cast<unsigned>(format));
			errorReason = "FSR 3: GPU NOT SUPPORTED (TYPED UAV LOADS)";
			return false;
		}
	}
	return true;
}

bool FSR3::CreateSharedTextures(ID3D11Device* device, int width, int height)
{
	Utilities::SafeRelease(dilatedDepth);
	Utilities::SafeRelease(dilatedMotionVectors);
	Utilities::SafeRelease(reconstructedPreviousDepth);

	D3D11_TEXTURE2D_DESC desc = {};
	desc.Width = static_cast<UINT>(width);
	desc.Height = static_cast<UINT>(height);
	desc.MipLevels = 1;
	desc.ArraySize = 1;
	desc.SampleDesc.Count = 1;
	desc.Usage = D3D11_USAGE_DEFAULT;
	desc.BindFlags = D3D11_BIND_SHADER_RESOURCE | D3D11_BIND_UNORDERED_ACCESS;

	desc.Format = DXGI_FORMAT_R32_FLOAT;
	bool ok = SUCCEEDED(device->CreateTexture2D(&desc, nullptr, &dilatedDepth));
	desc.Format = DXGI_FORMAT_R16G16_FLOAT;
	ok = ok && SUCCEEDED(device->CreateTexture2D(&desc, nullptr, &dilatedMotionVectors));
	desc.Format = DXGI_FORMAT_R32_UINT;
	ok = ok && SUCCEEDED(device->CreateTexture2D(&desc, nullptr, &reconstructedPreviousDepth));
	if (ok == false)
		Utilities::Log::Write("FSR 3: shared textures %dx%d could not be created", width, height);
	return ok;
}

void FSR3::DestroyContext()
{
	if (fsrContext)
	{
		ffxFsr3UpscalerContextDestroy(static_cast<FfxFsr3UpscalerContext*>(fsrContext));
		delete static_cast<FfxFsr3UpscalerContext*>(fsrContext);
		fsrContext = nullptr;
	}
	Utilities::SafeRelease(dilatedDepth);
	Utilities::SafeRelease(dilatedMotionVectors);
	Utilities::SafeRelease(reconstructedPreviousDepth);
	contextMaxWidth = contextMaxHeight = contextOutputWidth = contextOutputHeight = 0;
}

bool FSR3::EnsureContext(ID3D11Device* device, const UpscalerInputs& in)
{
	if (fsrContext && contextMaxWidth == in.maxRenderWidth && contextMaxHeight == in.maxRenderHeight &&
	    contextOutputWidth == in.outputWidth && contextOutputHeight == in.outputHeight && contextDynamic == in.dynamicResolution)
		return true;

	const int key[5] = { in.maxRenderWidth, in.maxRenderHeight, in.outputWidth, in.outputHeight, in.dynamicResolution ? 1 : 0 };
	if (memcmp(key, failedKey, sizeof(key)) == 0)
		return false;

	DestroyContext();
	if (CreateSharedTextures(device, in.maxRenderWidth, in.maxRenderHeight) == false)
	{
		memcpy(failedKey, key, sizeof(key));
		errorReason = "FSR 3 CONTEXT FAILED";
		return false;
	}

	ffxFsr3UpscalerSetGlobalDebugMessage(&LogMessage, FFX_API_CONFIGURE_GLOBALDEBUG_LEVEL_WARNINGS);

	FfxFsr3UpscalerContextDescription description = {};
	description.flags = FFX_FSR3UPSCALER_ENABLE_HIGH_DYNAMIC_RANGE | FFX_FSR3UPSCALER_ENABLE_DEPTH_INVERTED | FFX_FSR3UPSCALER_ENABLE_DEPTH_INFINITE |
	                    FFX_FSR3UPSCALER_ENABLE_AUTO_EXPOSURE | (in.dynamicResolution ? FFX_FSR3UPSCALER_ENABLE_DYNAMIC_RESOLUTION : 0);
	description.maxRenderSize.width = static_cast<uint32_t>(in.maxRenderWidth);
	description.maxRenderSize.height = static_cast<uint32_t>(in.maxRenderHeight);
	description.maxUpscaleSize.width = static_cast<uint32_t>(in.outputWidth);
	description.maxUpscaleSize.height = static_cast<uint32_t>(in.outputHeight);

	FfxInterface& callbacks = description.backendInterface;
	callbacks.fpGetEffectGpuMemoryUsage = &GetEffectGpuMemoryUsage;
	callbacks.fpCreateBackendContext = &CreateBackendContext;
	callbacks.fpGetDeviceCapabilities = &GetDeviceCapabilities;
	callbacks.fpDestroyBackendContext = &DestroyBackendContext;
	callbacks.fpCreateResource = &CreateResource;
	callbacks.fpRegisterResource = &RegisterResource;
	callbacks.fpGetResource = &GetResource;
	callbacks.fpUnregisterResources = &UnregisterResources;
	callbacks.fpRegisterStaticResource = &RegisterStaticResource;
	callbacks.fpGetResourceDescription = &GetResourceDescription;
	callbacks.fpDestroyResource = &DestroyResource;
	callbacks.fpMapResource = &MapResource;
	callbacks.fpUnmapResource = &UnmapResource;
	callbacks.fpStageConstantBufferDataFunc = &StageConstantBufferData;
	callbacks.fpCreatePipeline = &CreatePipeline;
	callbacks.fpDestroyPipeline = &DestroyPipeline;
	callbacks.fpScheduleGpuJob = &ScheduleGpuJob;
	callbacks.fpExecuteGpuJobs = &ExecuteGpuJobs;
	callbacks.device = device;

	FfxFsr3UpscalerContext* created = new FfxFsr3UpscalerContext();
	FfxErrorCode result = ffxFsr3UpscalerContextCreate(created, &description);
	if (result != FFX_OK)
	{
		Utilities::Log::Write("FSR 3: context %dx%d -> %dx%d failed: 0x%08X", in.maxRenderWidth, in.maxRenderHeight, in.outputWidth,
		                      in.outputHeight, static_cast<unsigned>(result));
		ffxFsr3UpscalerContextDestroy(created);
		delete created;
		DestroyContext();
		memcpy(failedKey, key, sizeof(key));
		errorReason = "FSR 3 CONTEXT FAILED";
		return false;
	}

	fsrContext = created;
	contextMaxWidth = in.maxRenderWidth;
	contextMaxHeight = in.maxRenderHeight;
	contextOutputWidth = in.outputWidth;
	contextOutputHeight = in.outputHeight;
	contextDynamic = in.dynamicResolution;
	Utilities::Log::Write("FSR %d.%d.%d created: max input %dx%d -> %dx%d%s", FFX_FSR3UPSCALER_VERSION_MAJOR, FFX_FSR3UPSCALER_VERSION_MINOR,
	                      FFX_FSR3UPSCALER_VERSION_PATCH, in.maxRenderWidth, in.maxRenderHeight, in.outputWidth, in.outputHeight,
	                      in.dynamicResolution ? " (dynamic resolution)" : "");
	return true;
}

bool FSR3::Execute(ID3D11DeviceContext* context, const UpscalerInputs& in)
{
	if (unsupported)
		return false;
	if (in.color == nullptr || in.motionVectors == nullptr || in.depth == nullptr || in.output == nullptr ||
	    in.renderWidth <= 0 || in.renderHeight <= 0 || in.renderWidth > in.maxRenderWidth || in.renderHeight > in.maxRenderHeight)
	{
		errorReason = "FSR 3: NO INPUTS";
		return false;
	}

	ID3D11Device* device = nullptr;
	context->GetDevice(&device);
	if (device == nullptr)
		return false;

	static bool checked = false;
	if (checked == false)
	{
		checked = true;
		if (CheckDevice(device) == false)
		{
			unsupported = true;
			device->Release();
			return false;
		}
	}

	bool ok = EnsureContext(device, in);
	device->Release();
	if (ok == false)
		return false;

	auto resource = [](ID3D11Resource* texture)
	{
		FfxApiResource result = {};
		result.resource = texture;
		result.description.type = FFX_API_RESOURCE_TYPE_TEXTURE2D;
		return result;
	};

	FfxFsr3UpscalerDispatchDescription dispatch = {};
	dispatch.commandList = context;
	dispatch.color = resource(in.color);
	dispatch.depth = resource(in.depth);
	dispatch.motionVectors = resource(in.motionVectors);
	dispatch.output = resource(in.output);
	dispatch.dilatedDepth = resource(dilatedDepth);
	dispatch.dilatedMotionVectors = resource(dilatedMotionVectors);
	dispatch.reconstructedPrevNearestDepth = resource(reconstructedPreviousDepth);
	dispatch.jitterOffset.x = in.jitterX;
	dispatch.jitterOffset.y = in.jitterY;
	/* Motion vectors are in render-resolution pixels; FSR 3 divides the scale by the render size */
	dispatch.motionVectorScale.x = 1.0f;
	dispatch.motionVectorScale.y = 1.0f;
	dispatch.renderSize.width = static_cast<uint32_t>(in.renderWidth);
	dispatch.renderSize.height = static_cast<uint32_t>(in.renderHeight);
	dispatch.upscaleSize.width = static_cast<uint32_t>(in.outputWidth);
	dispatch.upscaleSize.height = static_cast<uint32_t>(in.outputHeight);
	dispatch.enableSharpening = in.sharpness > 0.001f;
	dispatch.sharpness = in.sharpness;
	dispatch.frameTimeDelta = in.frameTimeMs;
	dispatch.preExposure = 1.0f;
	dispatch.reset = in.reset;
	/* Same convention as FSR 2 for reversed infinite depth: near = FLT_MAX, far = near plane */
	dispatch.cameraNear = FLT_MAX;
	dispatch.cameraFar = in.cameraNear;
	dispatch.cameraFovAngleVertical = in.fovY;
	dispatch.viewSpaceToMetersFactor = 0.01f;   // Unreal units are centimeters

	FfxErrorCode result = ffxFsr3UpscalerContextDispatch(static_cast<FfxFsr3UpscalerContext*>(fsrContext), &dispatch);
	if (result != FFX_OK)
	{
		static int errors = 0;
		if (errors++ < 10)
			Utilities::Log::Write("FSR 3: dispatch failed: 0x%08X", static_cast<unsigned>(result));
		errorReason = "FSR 3 DISPATCH FAILED";
		return false;
	}
	errorReason = "";
	return true;
}
